    model VARCHAR(100) PATH '$[1]',
    data_version VARCHAR(50) PATH '$[2]',
    source_url VARCHAR(1000) PATH '$[3]'
)) verified ON verified.sku = p.sku AND verified.model = p.model AND verified.data_version = p.data_version
JOIN product_specifications s ON s.product_id = p.id
SET s.parameters = JSON_ARRAY_APPEND(s.parameters, '$', JSON_OBJECT(
        'code', 'cableModularity', 'label', '模组类型', 'value', '全模组',
        'unit', '', 'sourceUrl', verified.source_url, 'note', ''
    )),
    p.revision = p.revision + 1
WHERE p.category = 'PSU'
  AND JSON_SEARCH(s.parameters, 'one', 'cableModularity', NULL, '$[*].code') IS NULL;
